class Producto:
    def __init__(self, nombre, precio, descuento_porcentaje=0):
        self.nombre = nombre
        self.precio = precio
        self.descuento_porcentaje = descuento_porcentaje

    @property
    def nombre(self):
        return self.__nombre

    @nombre.setter
    def nombre(self, valor):
        if not valor.strip():
            raise ValueError("Nombre vacío")
        self.__nombre = valor

    @property
    def precio(self):
        return self.__precio

    @precio.setter
    def precio(self, valor):
        if valor <= 0:
            raise ValueError("El precio debe ser positivo")
        self.__precio = valor

    @property
    def descuento_porcentaje(self):
        return self.__descuento

    @descuento_porcentaje.setter
    def descuento_porcentaje(self, valor):
        if not 0 <= valor <= 100:
            raise ValueError("El descuento debe estar entre 0 y 100")
        self.__descuento = valor

    @property
    def ahorro(self):
        return self.__precio * self.__descuento / 100

    @property
    def precio_final(self):
        return self.__precio - self.ahorro

    def info(self):
        print(f"{self.nombre}: ${self.precio:.2f} - {self.descuento_porcentaje}% "
              f"= ${self.precio_final:.2f} (ahorras ${self.ahorro:.2f})")

